217:     /// Send the spool once (see the module docs for the rule): under the sender lock, a snapshot
218:     /// read under the spool lock; lines queued more than 7 days ago and unreadable lines dropped;
219:     /// up to 100 events posted; then - under the spool lock again - exactly the delivered and the
220:     /// dropped lines removed from the CURRENT file. Never retries within the run.
221:     pub fn flush(&self) -> Result<FlushReport> {
222:         self.flush_with(|body| self.post_events(body))
223:     }
