225:     /// [`Spool::flush`] with an injected sender (tests hold the "network" while they append).
226:     pub fn flush_with(&self, post: impl Fn(&str) -> bool) -> Result<FlushReport> {
227:         let mut report = FlushReport::default();
228:         if self.dir.join(FORGET_PENDING).exists() {
229:             report.skipped = "a deletion of this instance is pending at the intake".into();
230:             return Ok(report);
231:         }
232:         let Some(_sender) = lock_within(&self.dir.join(FLUSH_LOCK), Duration::ZERO)? else {
233:             report.skipped = "another flush is running (its lock is held)".into();
234:             return Ok(report);
235:         };
236:         // the snapshot, read under the spool lock
237:         let snapshot = {
238:             let Some(_lock) = lock_within(&self.dir.join(SPOOL_LOCK), SENDER_LOCK_WAIT)? else {
239:                 report.skipped = "the spool lock stayed busy".into();
240:                 return Ok(report);
241:             };
242:             match fs::read_to_string(self.path()) {
243:                 Ok(t) => t,
244:                 Err(_) => return Ok(report),
245:             }
246:         };
247:         let lines: Vec<&str> = snapshot
248:             .lines()
249:             .map(|l| l.trim_end_matches('\r'))
250:             .filter(|l| !l.trim().is_empty())
251:             .collect();
252:         if lines.is_empty() {
253:             return Ok(report);
254:         }
255:         let cutoff = Utc::now().timestamp() - MAX_AGE_SECS;
256:         let mut remove: Vec<&str> = Vec::new();
257:         let mut fresh: Vec<(&str, String)> = Vec::new();
258:         for l in &lines {
259:             match parse_line(l) {
260:                 None => {
261:                     report.dropped_stale += 1;
262:                     remove.push(l);
263:                 }
264:                 Some(s) if s.queued <= cutoff => {
265:                     report.dropped_stale += 1;
266:                     remove.push(l);
267:                 }
268:                 Some(s) if s.kind == "event" => fresh.push((l, s.body)),
269:                 // another kind (a complaint line of a later wave): kept untouched
270:                 Some(_) => {}
271:             }
272:         }
273:         let batch: Vec<(&str, String)> = fresh.iter().take(MAX_BATCH).cloned().collect();
274:         if !batch.is_empty() {
275:             if self.hub.trim().is_empty() {
276:                 report.skipped = "the configured intake is refused".into();
277:             } else {
278:                 report.attempted = true;
279:                 let body = format!(
280:                     "{{\"events\":[{}]}}",
281:                     batch
282:                         .iter()
283:                         .map(|(_, b)| b.as_str())
284:                         .collect::<Vec<_>>()
285:                         .join(",")
286:                 );
287:                 if post(&body) {
288:                     report.sent = batch.len();
289:                     remove.extend(batch.iter().map(|(l, _)| *l));
290:                 }
291:             }
292:         }
293:         if !remove.is_empty() {
294:             self.remove_lines(&remove)?;
295:         }
296:         report.kept = self.pending();
297:         Ok(report)
298:     }
