300:     /// Remove exactly `lines` (one occurrence each) from the CURRENT spool file, under the spool
301:     /// lock, by an atomic replace; lines appended since the snapshot stay.
302:     fn remove_lines(&self, lines: &[&str]) -> Result<()> {
303:         let Some(_lock) = lock_within(&self.dir.join(SPOOL_LOCK), SENDER_LOCK_WAIT)? else {
304:             // not rewritten: the delivered lines are sent once more by the next flush
305:             return Err(Error::new("the spool lock stayed busy for the rewrite"));
306:         };
307:         let current = fs::read_to_string(self.path()).unwrap_or_default();
308:         let mut want: HashMap<&str, usize> = HashMap::new();
309:         for l in lines {
310:             *want.entry(l).or_insert(0) += 1;
311:         }
312:         let mut keep = String::new();
313:         for l in current.lines().map(|l| l.trim_end_matches('\r')) {
314:             if l.trim().is_empty() {
315:                 continue;
316:             }
317:             if let Some(n) = want.get_mut(l) {
318:                 if *n > 0 {
319:                     *n -= 1;
320:                     continue;
321:                 }
322:             }
323:             keep.push_str(l);
324:             keep.push('\n');
325:         }
326:         replace_atomic(&self.path(), keep.as_bytes())
327:     }
