199: /// `Invoke-TelemetryForget` with C3's pending-deletion record (F02-3): with a public reference
200: /// the intake is asked FIRST to delete every event and complaint of this instance; a DELETE the
201: /// intake does not confirm deletes NOTHING here (the salt, the spool, the references stay) and
202: /// records the pending deletion - the instance id and the reference a retry needs - in
203: /// `forget-pending.json`, which freezes telemetry (nothing spooled or sent) until a retry is
204: /// confirmed. `local` removes the local files only after a confirmed DELETE (or, without a
205: /// reference, after the user confirmed a local-only deletion through `confirm`). `hub`: the
206: /// resolved intake.
207: pub fn forget_at(
208:     hub: &crate::telemetry::Hub,
209:     dir: &Path,
210:     req: &ForgetRequest,
211:     confirm: impl Fn(&str) -> bool,
212: ) -> ForgetOutcome {
213:     const P: &str = "codex-telemetry";
214:     let mut out = ForgetOutcome::default();
215:     let pending = pending_deletion_in(dir);
216:     let explicit = req
217:         .public_ref
218:         .as_deref()
219:         .map(str::trim)
220:         .filter(|r| !r.is_empty())
221:         .map(str::to_string);
222:     let reference = explicit
223:         .clone()
224:         .or_else(|| pending.as_ref().map(|p| p.public_ref.clone()));
225:     let nothing = if req.local {
226:         "nothing was sent and nothing removed"
227:     } else {
228:         "nothing was sent"
229:     };
230:     if reference.is_none() && !req.local {
231:         out.exit = 1;
232:         out.lines.push(format!("{P}: -Forget needs -PublicRef <ref> (delete the data of this instance at the intake), -Local (remove the local spool and the salt), or both."));
233:         return out;
234:     }
235:     // the identity: the pending deletion's (the one already asked for), else this salt's
236:     let instance_id = pending
237:         .as_ref()
238:         .map(|p| p.instance_id.clone())
239:         .or_else(|| crate::telemetry::instance_id_if_exists_in(dir))
240:         .unwrap_or_default();
241:     out.instance_id = instance_id.clone();
242:     out.public_ref = reference.clone();
243:     if let Some(r) = &reference {
244:         if !is_public_ref(r) {
245:             out.exit = 1;
246:             out.lines.push(format!("{P}: -PublicRef '{r}' is not a public_ref (letters, digits, dot, dash, underscore); {nothing}."));
247:             return out;
248:         }
249:         if !hub.error.is_empty() {
250:             out.exit = 1;
251:             out.lines.push(format!("{P}: {}; {nothing}.", hub.error));
252:             return out;
253:         }
254:         if instance_id.is_empty() {
255:             out.exit = 1;
256:             out.lines.push(format!(
257:                 "{P}: this machine has no instance id (no salt {}): the intake holds nothing of it; {nothing}{}.",
258:                 dir.join("salt").display(),
259:                 if req.local { " (-Forget -Local alone removes the local files)" } else { "" }
260:             ));
261:             return out;
262:         }
263:     } else {
264:         // (F44-4) -Local alone: the intake keeps what was sent - said, then confirmed
265:         out.lines.push(format!(
