270:             out.exit = 1;
271:             out.lines.push(format!(
272:                 "{P}: nothing removed (no confirmation; -Yes removes without asking)."
273:             ));
274:             return out;
275:         }
276:     }
277:     out.confirmed = true;
278:     // the local deletion holds the sender lock and the spool lock across the DELETE and the
279:     // removal: no sender posts and no producer appends meanwhile
280:     let (_sender, _spool) = if req.local {
281:         let sender = match lock_within(&dir.join(FLUSH_LOCK), Duration::from_secs(10)) {
282:             Ok(Some(l)) => l,
283:             _ => {
284:                 out.exit = 1;
285:                 out.lines.push(format!(
286:                     "{P}: {nothing} - another flush is running (its lock is held); try again when it is done."
287:                 ));
288:                 return out;
289:             }
290:         };
291:         let spool = match lock_within(&dir.join(SPOOL_LOCK), Duration::from_secs(5)) {
292:             Ok(Some(l)) => l,
293:             _ => {
294:                 out.exit = 1;
295:                 out.lines.push(format!(
