339:                         dir.join(FORGET_PENDING).display()
340:                     ),
341:                     Err(e) => format!("the pending deletion could not be recorded ({e}) - run this command again"),
342:                 };
343:                 out.exit = 3;
344:                 if req.local {
345:                     out.lines.push(format!("{P}: the intake did not confirm the deletion ({why}); NOTHING was deleted - not there and not here: the salt (instance {instance_id}), the spool and the references are kept; {kept}."));
346:                 } else {
347:                     out.lines.push(format!("{P}: the intake did not confirm the deletion ({why}); nothing is deleted there - try again later (with the right -PublicRef); {kept}."));
