153: ) -> (Vec<String>, String) {
154:     let mut items = Vec::new();
155:     let key_re = regex::Regex::new(r"^[A-Za-z0-9_.]+=.+$").unwrap();
156:     let tilde_re = regex::Regex::new(r"^~[\\/]").unwrap();
157:     let literal_re = regex::Regex::new(r#"^(["'0-9\[{]|true$|false$)"#).unwrap();
158:     let reserved = [
159:         "model",
160:         "model_provider",
161:         "profile",
162:         "model_reasoning_effort",
