164:     ];
165:     for cfg_arg in values {
166:         let trimmed = cfg_arg.trim();
167:         if trimmed.is_empty() {
168:             continue;
169:         }
170:         for item in split_config_items(trimmed) {
171:             let item = item.trim();
172:             if !key_re.is_match(item) {
173:                 return (
174:                     Vec::new(),
175:                     format!("{label} '{item}' is malformed: expected key=value (key: letters, digits, _ and .; a non-empty value)."),
176:                 );
177:             }
178:             let eq = item.find('=').unwrap();
179:             let key = &item[..eq];
180:             let mut value = item[eq + 1..].to_string();
181:             if reserved.contains(&key) || key.starts_with("model_providers.") {
182:                 return (
183:                     Vec::new(),
184:                     format!("{label} '{item}' is refused: {key} is part of the reviewer identity and effort the bridge records (use -Model / -Provider / -Effort; providers belong in the Codex config)."),
185:                 );
186:             }
187:             if tilde_re.is_match(&value) {
